INSERT INTO "changelog_entry" ("entry_date", "summary") VALUES
('2026-11-22', '« Les menus du club » deviennent « 🍽️ Les repas du CLHUB ». Invite des membres ou des amis sans compte (ils ouvrent un lien), dis ce qu''il faut ramener, avec ou sans quantités, et chacun prend tout ou une partie, change d''avis ou propose une idée. En haut, chacun voit ce qu''il ramène (et se fait chambrer s''il n''a rien pris). La calculette propose la liste de courses selon le nombre de végés et de non-végés (raclette, fondue, tartiflette, crêpes, barbecue, apéro, pizzas). Et aussi : « Il manque encore », la relance, le rappel la veille, les cases « acheté », le partage des frais dans la Caisse et « Refaire ce repas ».');
